ALTER TABLE sales_order ADD COLUMN refund_status VARCHAR(20) NOT NULL DEFAULT 'NONE' CHECK(refund_status IN ('NONE','PARTIAL','FULL'));
ALTER TABLE wallet_transaction DROP CONSTRAINT wallet_transaction_transaction_type_check;
ALTER TABLE wallet_transaction ADD CONSTRAINT wallet_transaction_transaction_type_check CHECK(transaction_type IN ('RECHARGE','BONUS','CONSUMPTION','REFUND','ADJUSTMENT'));
CREATE TABLE sales_refund (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), order_id UUID NOT NULL REFERENCES sales_order(id), refund_no VARCHAR(40) NOT NULL, request_key UUID NOT NULL, status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','COMPLETED','CANCELLED')), total_cents BIGINT NOT NULL CHECK(total_cents>0), reason VARCHAR(240), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ, UNIQUE(store_id,refund_no), UNIQUE(order_id,request_key));
CREATE TABLE sales_refund_line (id UUID PRIMARY KEY, refund_id UUID NOT NULL REFERENCES sales_refund(id), order_line_id UUID NOT NULL REFERENCES sales_order_line(id), quantity SMALLINT NOT NULL DEFAULT 1 CHECK(quantity>0), refund_cents BIGINT NOT NULL CHECK(refund_cents>0));
CREATE TABLE refund_payment_record (id UUID PRIMARY KEY, tenant_id UUID NOT NULL REFERENCES tenant(id), store_id UUID NOT NULL REFERENCES store(id), refund_id UUID NOT NULL REFERENCES sales_refund(id), original_payment_id UUID NOT NULL REFERENCES payment_record(id), payment_method VARCHAR(30) NOT NULL CHECK(payment_method IN ('MEMBER_BALANCE','WECHAT','CASH')), amount_cents BIGINT NOT NULL CHECK(amount_cents>0), status VARCHAR(20) NOT NULL CHECK(status IN ('PENDING','COMPLETED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), completed_at TIMESTAMPTZ);
CREATE INDEX sales_refund_order_idx ON sales_refund(order_id,created_at DESC);
